<style scoped lang="scss" src="./donate-pill.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";
import { format } from "date-fns";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { has } from "../../util/has";
import DesktopOnly from "../../components/desktop-only/desktop-only";
import MobileOnly from "../../components/mobile-only/mobile-only";
import { currencyFormat } from "../../util/currency-format.js";


/**
 * This is a component to show basic information (name, time, amount) of a donation as a part of the timeline
 */
@Component({
  components: {
    Icon,
    MobileOnly,
    DesktopOnly
  }
})
export default class DonatePill extends Vue {
  /** The name associated with the entry */
  @Prop({ type: String, default: "" }) name;
  /**
   * Profile picture for the entry. If Two characters are used, then initials
   * will be rendered in place of the profile pic.
   */
  @Prop({ type: String, default: "" }) image;
  /** The date this item occurred */
  @Prop({ type: [Date, Number, String], default: new Date() }) time;
  /** The amount donated */
  @Prop({ type: Number, default: 0 }) amount;
  /** Display the quote text associated with this entry */
  @Prop({ type: Boolean, default: false }) showQuote;
  /** A quote or blurb of text associated with this donation event. */
  @Prop({ type: String, default: "" }) quote;
  /** Currency format to use for the user. */
  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;

  @Prop({
    type: Boolean,
    default: true
  })
  horizon;

  quoteSignColor = "#F9FAFB";
  quoteSignShape = IconShape.QUOTE;
  quoteSignSize = 10;

  get timeString() {
    let time = this.time;

    if (typeof time === "number" || typeof time == "string") {
      time == new Date(this.time);

      if (time.toDateString() === "Invalid Date") {
        console.warn("Wrong date format");
      }
    }

    return format(time, "p").toLowerCase();
  }

  get cardContainerStyle() {
    if (this.showQuote) {
      return {
        flex: "0 1 350px",
        minWidth: "350px",
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-end",
        paddingRight: "32px",
        boxSizing: "border-box"
      };
    }

    return {};
  }

  get initials() {
    if (this.image.length === 2) return this.image;
    return null;
  }

  get amountString() {
    return currencyFormat(this.amount);
  }
}
</script>

<template>
  <div :class="['DonatePill', this.horizon ? '' : 'DonatePill--vertical']">
    <div class="DonatePill__CardContainer" :style="cardContainerStyle">
      <div class="DonatePill__Card">
        <div
          class="DonatePill__Left"
          v-bind:style="{ backgroundImage: `url(${image})` }"
        >
          <span v-if="initials" class="DonatePill__Initials">{{
            initials
          }}</span>
        </div>
        <div class="DonatePill__Middle">
          <div class="DonatePill__Name">{{ name }}</div>
          <div class="DonatePill__Time">{{ timeString }}</div>
        </div>
        <div class="DonatePill__Right">
          <div class="DonatePill__Amount">
            {{ `${this.currency} ${amountString}` }}
          </div>
        </div>
      </div>
    </div>
    <MobileOnly>
      <div v-if="showQuote" class="DonatePill__QuoteSignContainer">
        <div class="DonatePill__Line"></div>
        <div class="DonatePill__QuoteSign">
          <Icon
            :shape="quoteSignShape"
            :color="quoteSignColor"
            :size="quoteSignSize"
          />
        </div>
        <div class="DonatePill__Line"></div>
      </div>
    </MobileOnly>
    <DesktopOnly>
      <div v-if="showQuote" class="DonatePill__QuoteSignContainer">
        <div v-if="!horizon" class="DonatePill__Line"></div>
        <div class="DonatePill__QuoteSign">
          <Icon
            :shape="quoteSignShape"
            :color="quoteSignColor"
            :size="quoteSignSize"
          />
        </div>
        <div v-if="!horizon" class="DonatePill__Line"></div>
      </div>
    </DesktopOnly>
    <div v-if="showQuote" class="DonatePill__Quote">{{ quote }}</div>
  </div>
</template>
